def compute_rsi(close, period=14):
    delta = close.diff()
    gain = delta.where(delta > 0, 0).ewm(alpha=1/period, adjust=False).mean()
    loss = (-delta.where(delta < 0, 0)).ewm(alpha=1/period, adjust=False).mean()
    rs = gain / loss
    rsi = 100 - (100 / (1 + rs))
    return rsi

def compute_ema(close, period):
    return close.ewm(span=period, adjust=False).mean()

def compute_atr(high, low, close, period=14):
    tr = (high - low).combine((close - close.shift()).abs(), max).combine((close.shift() - low).abs(), max)
    atr = tr.ewm(alpha=1/period, adjust=False).mean()
    return atr

def calc_best_expiry(rsi_now, atr_now, price, bullish, bearish, trend_strength):
    atr_pct = (atr_now / price * 100) if price else 0
    if rsi_now > 75 or rsi_now < 25:
        return "1 د", "انعكاس قوي - دخول سريع"
    if atr_pct > 0.15:
        return "1 د", "تذبذب عالي - سكالبينج"
    if trend_strength >= 4 and atr_pct > 0.08:
        return "2 د", "ترند قوي جدا"
    if trend_strength >= 3:
        return "3 د", "ترند مستمر - افضل مدة"
    return "5 د", "تجميع - يحتاج وقت"

def analyze_real_tradingview(symbol):
    try:
        ticker = yf.Ticker(symbol)
        df_m5 = ticker.history(period="2d", interval="5m")
        if df_m5.empty or len(df_m5) < 30:
            df_m5 = ticker.history(period="5d", interval="15m")
            if df_m5.empty:
                return None
        df_m15 = ticker.history(period="5d", interval="15m")
        df_h1 = ticker.history(period="1mo", interval="1h")
        
        close = df_m5['Close']
        high = df_m5['High']
        low = df_m5['Low']
        price = float(close.iloc[-1])
        
        rsi = compute_rsi(close, 14)
        rsi_now = float(rsi.iloc[-1])
        rsi_prev = float(rsi.iloc[-2]) if len(rsi) > 1 else rsi_now
        
        ema20 = compute_ema(close, 20)
        ema50 = compute_ema(close, 50)
        ema200 = compute_ema(close, 200)
        ema20_now = float(ema20.iloc[-1])
        ema50_now = float(ema50.iloc[-1])
        ema200_now = float(ema200.iloc[-1]) if len(ema200) > 0 else ema50_now
        
        ema12 = compute_ema(close, 12)
        ema26 = compute_ema(close, 26)
        macd = ema12 - ema26
        signal_line = macd.ewm(span=9, adjust=False).mean()
        macd_now = float(macd.iloc[-1])
        macd_sig_now = float(signal_line.iloc[-1])
        
        atr = compute_atr(high, low, close, 14)
        atr_now = float(atr.iloc[-1]) if len(atr) > 0 else 0
        
        last_high = float(high.tail(20).max())
        last_low = float(low.tail(20).min())
        
        trend_m15_bullish = True
        try:
            if not df_m15.empty and len(df_m15) > 20:
                close15 = df_m15['Close']
                ema20_15 = compute_ema(close15, 20).iloc[-1]
                trend_m15_bullish = float(close15.iloc[-1]) > float(ema20_15)
        except: pass
        
        trend_h1_bullish = True
        try:
            if not df_h1.empty and len(df_h1) > 50:
                close_h1 = df_h1['Close']
                ema50_h1 = compute_ema(close_h1, 50).iloc[-1]
                trend_h1_bullish = float(close_h1.iloc[-1]) > float(ema50_h1)
        except: pass
        
        bullish = 0
        bearish = 0
        
        if price > ema20_now: bullish += 1
        else: bearish += 1
        if ema20_now > ema50_now: bullish += 1
        else: bearish += 1
        if price > ema200_now: bullish += 1
        else: bearish += 1
        if 50 < rsi_now < 70 and rsi_now > rsi_prev: bullish += 1
        elif 30 < rsi_now < 50 and rsi_now < rsi_prev: bearish += 1
        elif rsi_now > 70: bearish += 1
        elif rsi_now < 30: bullish += 1
        if macd_now > macd_sig_now: bullish += 1
        else: bearish += 1
        if price >= last_high * 0.9995: bullish += 1
        if price <= last_low * 1.0005: bearish += 1
        if trend_m15_bullish: bullish += 1
        else: bearish += 1
        if trend_h1_bullish: bullish += 1
        else: bearish += 1
        
        total_points = max(bullish, bearish)
        trend_strength = total_points
        
        if bullish >= 5 and bullish > bearish:
            signal = "CALL"
            signal_ar = "صعود"
        elif bearish >= 5 and bearish > bullish:
            signal = "PUT"
            signal_ar = "هبوط"
        else:
            if bullish > bearish:
                signal = "CALL"
                signal_ar = "صعود"
            else:
                signal = "PUT"
                signal_ar = "هبوط"
        
        score = 50 + (bullish * 6 if signal=="CALL" else bearish * 6)
        score += max(0, (rsi_now - 50) if signal=="CALL" else (50 - rsi_now)) * 0.4
        if abs(macd_now - macd_sig_now) > 0.00005:
            score += 4
        if (trend_m15_bullish and signal=="CALL") or (not trend_m15_bullish and signal=="PUT"):
            score += 5
        if (trend_h1_bullish and signal=="CALL") or (not trend_h1_bullish and signal=="PUT"):
            score += 5
            
        score = min(97, max(60, int(score)))
        conf = min(94, max(70, score - random.randint(1,4)))
        
        if score >= 88:
            strength = "قوية جدا 🔥"
            conf_text = "ممتازة"
        elif score >= 80:
            strength = "قوية"
            conf_text = "جيدة جدا"
        else:
            strength = "متوسطة"
            conf_text = "جيدة"
        
        best_expiry, expiry_reason = calc_best_expiry(rsi_now, atr_now, price, bullish, bearish, trend_strength)
        
        return {
            "pair": CLEAN.get(symbol,symbol),
            "flag": FLAGS.get(symbol,""),
            "signal": signal,
            "signal_ar": signal_ar,
            "conf": conf,
            "score": score,
            "price": price,
            "strength": strength,
            "conf_text": conf_text,
            "rsi_m5": rsi_now,
            "align_num": trend_strength,
            "symbol": symbol,
            "atr": atr_now,
            "best_expiry": best_expiry,
            "expiry_reason": expiry_reason,
            "m15_confirm": trend_m15_bullish,
            "h1_confirm": trend_h1_bullish
        }
    except Exception as e:
        logging.error(f"analyze {symbol} {e}")
        return None

def get_best():
    results = []
    for sym in SYMBOLS:
        r = analyze_real_tradingview(sym)
        if r:
            results.append(r)
            time.sleep(0.2)
    if not results: return None
    results.sort(key=lambda x: (x["score"], x["align_num"]), reverse=True)
    return results[0]

def get_all_signals():
    results = []
    for sym in SYMBOLS:
        r = analyze_real_tradingview(sym)
        if r:
            results.append(r)
    return sorted(results, key=lambda x: x["score"], reverse=True)

def format_message_ar(r):
    arrow = "⬆️" if r["signal"]=="CALL" else "⬇️"
    color = "🟢" if r["signal"]=="CALL" else "🔴"
    price_fmt = f"{r['price']:.5f}"
    msg = f"💱 {r['pair']} {r['flag']}\n"
    msg += f"{color} {r['signal_ar']} {arrow} | ⏱️ {r['best_expiry']} ({r['expiry_reason']})\n"
    msg += f"\n🎯 الثقة: {r['conf']}% {r['conf_text']}\n"
    msg += f"⚡ القوة: {r['score']}/100 {r['strength']}\n"
    msg += f"\n💰 دخول: {price_fmt}\n"
    msg += f"📊 RSI: {r['rsi_m5']:.1f} | {r['align_num']}/8 مؤشرات\n"
    msg += f"📈 M15: {'✅' if (r['m15_confirm'] and r['signal']=='CALL') or (not r['m15_confirm'] and r['signal']=='PUT') else '❌'} | H1: {'✅' if (r['h1_confirm'] and r['signal']=='CALL') or (not r['h1_confirm'] and r['signal']=='PUT') else '❌'}\n"
    msg += f"\n⏰ مدة Pocket Option: {r['best_expiry']}"
    return msg

