last_global_send = 0
last_sent_info = ""

async def check_signals(context: ContextTypes.DEFAULT_TYPE):
    global last_global_send, last_sent_info
    now = time.time()
    if now - last_global_send < 120: return
    try:
        best = get_best()
        if not best: return
        if best["score"] < 88: return
        if last_sent_info == best["pair"] and (now - last_global_send) < 300: return
        sent = 0
        for cid, ok in list(state.get("auth",{}).items()):
            if not ok: continue
            if state.get("paused",{}).get(cid): continue
            if not state.get("auto",{}).get(cid): continue
            try:
                await send_signal_with_image(context, cid, best)
                sent += 1
            except: pass
        if sent > 0:
            last_global_send = now
            last_sent_info = best["pair"]
    except Exception as e:
        logging.error(f"check_signals {e}")

async def clean(context: ContextTypes.DEFAULT_TYPE): pass

def main():
    try:
        requests.get(f"https://api.telegram.org/bot{BOT_TOKEN}/deleteWebhook?drop_pending_updates=true", timeout=5)
        time.sleep(1)
    except: pass
    app = Application.builder().token(BOT_TOKEN).build()
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CallbackQueryHandler(buttons))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, handle_message))
    app.job_queue.run_repeating(check_signals, interval=60, first=20)
    app.job_queue.run_repeating(clean, interval=3600, first=30)
    logging.info("POCKET OPTION 7 MARKETS + TRADINGVIEW + AUTO EXPIRY + IMAGES READY")
    app.run_polling(drop_pending_updates=True, close_loop=False, allowed_updates=Update.ALL_TYPES)

if __name__ == "__main__":
    threading.Thread(target=run_flask, daemon=True).start()
    time.sleep(2)
    main()
